29: function setSecrets(flyApp, token, kv) {
30:   const pairs = Object.entries(kv).map(([k, v]) => `${k}=${v}`);
31:   if (!pairs.length) return;
32:   const r = run(['secrets', 'set', '--app', flyApp, '--stage', ...pairs], token, { capture: true });
33:   const out = (r.stdout || '') + (r.stderr || '');
34:   if (r.status !== 0 && !/no change/i.test(out)) throw new Error(`flyctl secrets set failed:\n${out.trim()}`);
35: }
