28:   });
29:   if (!resp.ok) {
30:     const text = await resp.text();
31:     if (!/taken|already/i.test(text)) throw new Error(`fly app create failed (${resp.status}): ${text}`);
32:   }
33:   await gql(env, 'mutation($app: ID!) { allocateIpAddress(input: {appId: $app, type: shared_v4}) { app { name } } }', { app: flyApp });
